<script setup>import {ref} from 'vue';import {Head,Link,router} from '@inertiajs/vue3';import AppLayout from '@/Layouts/AppLayout.vue';import Button from '@/Components/UI/Button.vue';import Icon from '@/Components/UI/Icon.vue';import HrNav from '../Partials/HrNav.vue';import {usePermissions} from '@/composables/usePermissions';defineOptions({layout:AppLayout});const props=defineProps({shifts:Object,filters:Object,summary:Object});const {can}=usePermissions();const from=ref(props.filters.from),to=ref(props.filters.to);const filter=()=>router.get('/administration/planning',{from:from.value,to:to.value},{preserveState:true,replace:true});const dt=v=>new Intl.DateTimeFormat('fr-FR',{weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(v));</script>
<template><Head title="Planning RH"/><div class="space-y-5"><HrNav/><header class="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p class="text-xs font-bold uppercase tracking-[.15em] text-cyan-600">Organisation des équipes</p><h1 class="mt-1 font-heading text-3xl font-bold text-slate-800 dark:text-white">Planning</h1><p class="mt-2 text-sm text-slate-500">Vue chronologique des créneaux et affectations.</p></div><div class="flex flex-wrap gap-2"><Button v-if="can('planning.print')" :as="Link" :href="`/administration/planning/print?from=${from}&to=${to}`" size="rg" variant="white-outline"><Icon name="printer"/><span class="ms-2">Imprimer</span></Button><Button v-if="can('planning.export')" as="a" :href="`/administration/planning/export?from=${from}&to=${to}`" size="rg" variant="white-outline"><Icon name="download"/><span class="ms-2">Exporter</span></Button><Button v-if="can('planning.create')" :as="Link" href="/administration/planning/create" size="rg"><Icon name="plus"/><span class="ms-2">Nouveau créneau</span></Button></div></header><section class="grid gap-3 sm:grid-cols-2"><div class="rounded-xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-900 dark:bg-gray-950"><p class="text-xs font-bold uppercase text-slate-400">Créneaux</p><p class="mt-2 text-2xl font-black">{{summary.shifts}}</p></div><div class="rounded-xl border border-gray-200 bg-white p-4 shadow-sm dark:border-gray-900 dark:bg-gray-950"><p class="text-xs font-bold uppercase text-slate-400">Employés planifiés</p><p class="mt-2 text-2xl font-black">{{summary.employees}}</p></div></section><section class="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-sm dark:border-gray-900 dark:bg-gray-950"><form class="flex flex-wrap gap-3 border-b border-gray-200 p-4 dark:border-gray-900" @submit.prevent="filter"><input v-model="from" type="date" class="h-10 rounded-lg border border-gray-200 px-3 text-sm dark:border-gray-800 dark:bg-gray-950"><input v-model="to" type="date" class="h-10 rounded-lg border border-gray-200 px-3 text-sm dark:border-gray-800 dark:bg-gray-950"><Button size="rg">Afficher la période</Button></form><div class="divide-y divide-gray-100 dark:divide-gray-900"><article v-for="shift in shifts.data" :key="shift.uuid" class="grid gap-4 p-5 transition hover:bg-gray-50/60 dark:hover:bg-gray-1000/30 lg:grid-cols-[180px_minmax(0,1fr)_minmax(0,.8fr)_auto]"><div><p class="text-sm font-bold text-cyan-700">{{dt(shift.starts_at)}}</p><p class="mt-1 text-xs text-slate-400">jusqu’au {{dt(shift.ends_at)}}</p></div><div><h2 class="font-bold text-slate-800 dark:text-white">{{shift.employee.name}}</h2><p class="mt-1 font-mono text-xs text-slate-400">{{shift.employee.employee_number}}</p></div><div><p class="text-sm font-semibold text-slate-700 dark:text-slate-200">{{shift.title||'Créneau sans objet'}}</p><p class="mt-1 text-xs text-slate-400">{{shift.department||shift.employee.department||'Département non renseigné'}}</p><p v-if="shift.observation" class="mt-2 text-xs text-slate-500">{{shift.observation}}</p></div><Button v-if="can('planning.update')" :as="Link" :href="`/administration/planning/${shift.uuid}/edit`" icon size="rg" variant="white-outline"><Icon name="edit"/></Button></article><p v-if="!shifts.data.length" class="py-14 text-center text-sm text-slate-400">Aucun créneau sur cette période.</p></div></section></div></template>
